'use client';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { SortableContext, arrayMove, useSortable, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { useState } from 'react';

function Row({ id }: { id: string }) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({ id });
  return <li ref={setNodeRef} style={{ transform: CSS.Transform.toString(transform), transition }} {...attributes} {...listeners}>{id}</li>;
}

export function {{list_name}}() {
  const [items, setItems] = useState(['a','b','c']);
  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={(e) => {
      if (e.over && e.active.id !== e.over.id) setItems(items => arrayMove(items, items.indexOf(String(e.active.id)), items.indexOf(String(e.over!.id))));
    }}>
      <SortableContext items={items} strategy={verticalListSortingStrategy}>
        <ul>{items.map(id => <Row key={id} id={id} />)}</ul>
      </SortableContext>
    </DndContext>
  );
}
